mod outer {
    pub mod inner {
        pub(super) fn only_outer() -> u32 {
            1
        }
        pub(crate) fn whole_crate() -> u32 {
            2
        }
    }
    pub fn via_outer() -> u32 {
        inner::only_outer()
    }
}

fn main() {
    println!("{} {}", outer::via_outer(), outer::inner::whole_crate());
}

